$(function () {
    $('[data-reviews-endpoint]').each(function () {
        var $container = $(this);
        var endpoint   = $container.data('reviews-endpoint');
        var params = {
            limit:      $container.data('limit')      || 6,
            min_rating: $container.data('min-rating') || 5,
            scope:      $container.data('scope')      || 'home',
        };
        var tag = $container.data('tag');
        if (tag) { params.tag = tag; }
        $.get(endpoint, params, function (res) {
            $container.html(res.html);
            if (res.stats) {
                var $section = $container.closest('[data-reviews-section]');
                $section.find('.ht-score').text(res.stats.avg_rating);
                $section.find('.ht-count-num').text(res.stats.total);
            }
            if ($container.hasClass('swiper-wrapper') && typeof Swiper !== 'undefined') {
                var $swiperEl = $container.closest('.swiper');
                new Swiper($swiperEl[0], {
                    loop: true,
                    slidesPerView: 1,
                    spaceBetween: 24,
                    navigation: {
                        nextEl: $swiperEl.closest('.about-testimonial-area').find('.testimonial-next')[0],
                        prevEl: $swiperEl.closest('.about-testimonial-area').find('.testimonial-prev')[0],
                    },
                });
            }
        });
    });
});